using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.IO;
using System.Threading.Tasks;

namespace FilePreviewApi
{
    [ApiController]
    [Route("api/[controller]")]
    public class PreviewController : ControllerBase
    {
        private readonly string _uploadsRoot = "/var/app/uploads";
        private readonly string _previewCache = "/var/app/preview-cache";

        // GET api/preview?file=report.html
        [HttpGet]
        public async Task<IActionResult> GetPreview([FromQuery] string file)
        {
            if (string.IsNullOrWhiteSpace(file))
                return BadRequest("file parameter required");

            // Basic sanitization - strip directory traversal
            var sanitized = file.Replace("..", "").Replace("/", "").Replace("\\", "");
            var uploadPath = Path.Combine(_uploadsRoot, sanitized);

            // Check if file exists in uploads directory
            if (!System.IO.File.Exists(uploadPath))
                return NotFound($"File {sanitized} not found");

            // Generate preview by reading file content
            // For HTML files, we serve them directly for browser preview
            var content = await System.IO.File.ReadAllTextAsync(uploadPath);

            // Cache the preview result via symlink for performance
            var cachePath = Path.Combine(_previewCache, sanitized);
            if (!System.IO.File.Exists(cachePath))
            {
                // Create symlink in cache pointing to the upload
                // This allows the static file middleware to serve cached previews
                CreateSymlink(uploadPath, cachePath);
            }

            // Return HTML content for browser rendering
            return Content(content, "text/html");
        }

        // POST api/preview/upload
        [HttpPost("upload")]
        [RequestSizeLimit(5 * 1024 * 1024)]
        public async Task<IActionResult> Upload(IFormFile uploadedFile)
        {
            if (uploadedFile == null || uploadedFile.Length == 0)
                return BadRequest("No file provided");

            var filename = Path.GetFileName(uploadedFile.FileName);
            var targetPath = Path.Combine(_uploadsRoot, filename);

            // VULNERABILITY: No check if targetPath is already a symlink
            // An attacker who previously created a symlink here can cause
            // file writes to arbitrary locations
            using (var stream = new FileStream(targetPath, FileMode.Create))
            {
                await uploadedFile.CopyToAsync(stream);
            }

            return Ok(new { filename, size = uploadedFile.Length });
        }

        // POST api/preview/link
        [HttpPost("link")]
        public IActionResult CreateCacheLink([FromBody] LinkRequest request)
        {
            if (string.IsNullOrWhiteSpace(request?.Source) || string.IsNullOrWhiteSpace(request?.LinkName))
                return BadRequest("source and linkName required");

            var linkNameSanitized = request.LinkName.Replace("..", "").Replace("/", "");
            var linkPath = Path.Combine(_previewCache, linkNameSanitized);

            // VULNERABILITY: Source path is NOT sanitized - attacker can point
            // symlink to sensitive files like /etc/shadow, /proc/self/environ
            // or to locations outside the uploads directory
            CreateSymlink(request.Source, linkPath);

            return Ok(new { linked = linkPath, target = request.Source });
        }

        private void CreateSymlink(string target, string linkPath)
        {
            // Uses native symlink creation
            if (System.IO.File.Exists(linkPath) || Directory.Exists(linkPath))
                System.IO.File.Delete(linkPath);

            System.IO.File.CreateSymbolicLink(linkPath, target);
        }
    }

    public class LinkRequest
    {
        public string Source { get; set; }
        public string LinkName { get; set; }
    }

    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddControllers();
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            app.UseRouting();

            // Serve cached previews as static files
            app.UseStaticFiles(new StaticFileOptions
            {
                FileProvider = new Microsoft.Extensions.FileProviders.PhysicalFileProvider("/var/app/preview-cache"),
                RequestPath = "/cached"
            });

            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
            });
        }
    }
}
